#!/usr/bin/env python3
"""Writes contents/code/mdi-names.mjs: the names of all icons in contents/ui/mdi/mdi.svgz,
for the icon picker. Run again whenever mdi.svgz is replaced."""
import gzip
import pathlib
import re

root = pathlib.Path(__file__).resolve().parent.parent
svg = gzip.decompress((root / "contents/ui/mdi/mdi.svgz").read_bytes()).decode("utf-8")
names = sorted(set(re.findall(r'\bid="([a-z0-9-]+)"', svg)))
out = root / "contents/code/mdi-names.mjs"
out.write_text(
    "// Generated by tools/generate-mdi-names.py from contents/ui/mdi/mdi.svgz – do not edit\n"
    "export const NAMES = Object.freeze(" + repr(names).replace("'", '"') + ")\n",
    encoding="utf-8")
print(f"{len(names)} icon names written to {out.relative_to(root)}")
